mapper.insert:
INSERT INTO earthquake_event (
    seq, lat, lon, loc, rem, tm_fc, msc, mt, expose_yn
) VALUES (
    #{seq}, #{lat}, #{lon}, #{loc}, #{rem}, #{tmFc}, #{msc}, #{mt}, 'Y'
)
ON DUPLICATE KEY UPDATE
    loc = VALUES(loc),
    mt = VALUES(mt),
    rem = VALUES(rem);

INSERT INTO typhoon_info (
    typhoon_year, typhoon_no, typhoon_name, typhoon_name_desc, 
    typhoon_active_yn, typhoon_first_location
) VALUES (
    #{typhoonYear}, #{typhoonNo}, #{typhoonName}, #{typhoonNameDesc}, 
    #{typhoonActiveYn}, #{typhoonFirstLocation}
)
ON DUPLICATE KEY UPDATE
    typhoon_active_yn = VALUES(typhoon_active_yn),
    typhoon_name_desc = VALUES(typhoon_name_desc);

INSERT INTO lnld_forecast_info (
    lnld_frcst_nm, sgg_nm, predc_anls_dt, data_std_dt, use_yn, reg_dt
) VALUES (
    #{lnldFrcstNm}, #{sggNm}, #{predcAnlsDt}, CURRENT_TIMESTAMP, 'Y', CURRENT_TIMESTAMP
)
